/** Authored tasks are served in rank order, then in the order written here. */
const TASKS: AuthoredTask[] = (() => {
  const count: Record<number, number> = {};
  return RAW_TASKS.map((t) => ({ ...t, seq: (count[t.rank] = (count[t.rank] ?? 0) + 1) }));
})();

// ---------------------------------------------------------------------------------------------- sorting labels
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
/** [bin, what is written on the crate, "A box of" …] */
type Food = [bin: string, name: string, box: string];
const named = (fs: Food[]) => pat(fs.map(([b, nm]) => [cap(nm), b]));
const boxed = (fs: Food[]) => pat(fs.map(([b, nm, c]) => [`${c} ${nm}`, b]));
const fresh = (fs: Food[]) => pat(fs.filter(([b]) => b !== 'shelf').map(([b, nm]) => [`Fresh ${nm}`, b]));
const kept = (fs: Food[]) => pat(fs.map(([b, nm]) => [`${cap(nm)}. ${b === 'cold' ? 'Keep cold.' : b === 'shelf' ? 'Keep dry.' : b === 'freezer' ? 'Keep frozen.' : 'Keep in the basket.'}`, b]));

